SELECT r.id AS id, r.name AS resourceName, r.resource_type AS resourceType, r.media_type AS mediaType, r.channel AS channel, r.rate_card AS rateCard, r.position AS position, r.daily_impressions AS dailyImpressions, r.unit_price AS unitPrice, r.status AS status, r.business_entity_id AS businessEntityId, be.name AS businessEntityName, r.remark AS remark, r.organization_id AS organizationId, r.create_time AS createTime FROM ad_resource r LEFT JOIN ad_business_entity be ON be.id = r.business_entity_id AND be.deleted = 0 WHERE r.organization_id = #{request.organizationId} AND r.deleted = 0
AND r.resource_type = #{request.resourceType}
AND r.status = #{request.status}
AND (r.name LIKE CONCAT('%', #{request.keyword}, '%') OR r.channel LIKE CONCAT('%', #{request.keyword}, '%'))
AND r.business_entity_id IN
#{eid}
